const CONFIG = {
  COMPANY_NAME: "Valfin Tech",
  OWNER_PHONE: "+18575261499",
  OWNER_EMAIL: "valfintechnologies@gmail.com",
  TWILIO_FROM_NUMBER: "+18889839308",
  EMAIL_ALERTS_ENABLED: true,
  SMS_ALERTS_ENABLED: false,
  DEFAULT_TIMEZONE: "America/New_York"
};

function isChecked(v) {
  if (v === true) return true;
  if (typeof v === "number") return v === 1;
  return String(v || "").trim().toUpperCase() === "TRUE";
}

const rows = $input.all().map(i => i.json);
const out = [];

for (const row of rows) {
  const status = String(row["Status"] || "").trim();
  if (status !== "Scheduled") continue;
  if (!isChecked(row["Notify Customer"])) continue;

  const apptDate = String(row["Appt Date"] || "").trim();
  const apptTime = String(row["Appt Time"] || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(apptDate)) continue;
  if (!/^\d{1,2}:\d{2}\s*(AM|PM)$/i.test(apptTime)) continue;

  const notifiedDate = String(row["Notified Appt Date"] || "").trim() || apptDate;
  const notifiedTime = String(row["Notified Appt Time"] || "").trim() || apptTime;

  out.push({ json: Object.assign({}, row, {
    oldApptDate: notifiedDate,
    oldApptTime: notifiedTime,
    newApptDate: apptDate,
    newApptTime: apptTime,
    emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
    smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
    ownerEmail: CONFIG.OWNER_EMAIL,
    ownerPhone: CONFIG.OWNER_PHONE,
    twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
    companyName: CONFIG.COMPANY_NAME,
    timezone: CONFIG.DEFAULT_TIMEZONE
  })});
}

return out;

function normalizePhone(raw) {
  const digits = String(raw || "").replace(/\D/g, "");
  if (digits.length === 11 && digits.startsWith("1")) return "+" + digits;
  if (digits.length === 10) return "+1" + digits;
  return null;
}

function formatFriendlyDate(dateStr, zone) {
  const parts = String(dateStr).split("-").map(Number);
  return DateTime.fromObject({ year: parts[0], month: parts[1], day: parts[2] }, { zone: zone }).toFormat("cccc, LLLL d");
}

return $input.all().map(item => {
  const j = item.json;
  const firstName = String(j["Customer Name"] || "").trim().split(" ")[0] || "there";
  const newFriendly = formatFriendlyDate(j.newApptDate, j.timezone) + " at " + j.newApptTime;
  const oldFriendly = formatFriendlyDate(j.oldApptDate, j.timezone) + " at " + j.oldApptTime;

  const smsMessage = "Hi " + firstName + ", thank you for scheduling with " + j.companyName + ". Unfortunately, we weren't available at your originally requested appointment time. We've reserved " + newFriendly + " instead. Please reply YES to confirm this appointment, or reply NO if this time doesn't work for you. Thank you.";

  const emailSubject = "Reschedule Notice Sent: " + j["Customer Name"] + " (" + j["Appt ID"] + ")";
  const emailHtml = "<p>Appointment <strong>" + j["Appt ID"] + "</strong> for <strong>" + j["Customer Name"] + "</strong> was updated by the owner and the customer has been notified.</p>" +
    "<p>Previously communicated time: " + oldFriendly + "<br>New time: " + newFriendly + "</p>" +
    "<p>Reschedule Status set to <strong>Pending Customer Confirmation</strong> - awaiting the customer's YES/NO reply.</p>";

  const ownerSmsMessage = "Reschedule notice sent: " + j["Customer Name"] + " (" + j["Appt ID"] + ") - new time " + newFriendly + ". Awaiting customer YES/NO confirmation.";

  return { json: Object.assign({}, j, {
    customerPhone: normalizePhone(j["Phone"]),
    smsMessage: smsMessage,
    emailSubject: emailSubject,
    emailHtml: emailHtml,
    ownerSmsMessage: ownerSmsMessage
  })};
});
